internal static class Program {
 [STAThread] static void Main(){Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
  try{var root=new DirectoryInfo(AppContext.BaseDirectory);while(root!=null&&!File.Exists(Path.Combine(root.FullName,"agent","start.ps1")))root=root.Parent;if(root==null)throw new Exception("找不到Agent运行文件。请保留完整的ArcGISPro-Codex目录，不要只移动EXE。");Application.Run(new MainForm(root.FullName));}
  catch(Exception ex){MessageBox.Show(ex.Message,"ArcGIS Agent 无法启动",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
}
internal record ProSession(int Id,string Title){public override string ToString()=>$"{Title}  （进程 {Id}）";}
internal record Profile(string Id,string Name,string Model){public override string ToString()=>Name+" · "+Model;}
internal record Artifact(string Path){public override string ToString()=>System.IO.Path.GetExtension(Path).ToLowerInvariant()==".png"?"地图预览（PNG）":"地图成品（PDF）";}
