 string SessionPath=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ArcGISProCodex","desktop-session.json");
 void SaveSession(){try{Directory.CreateDirectory(Path.GetDirectoryName(SessionPath)!);File.WriteAllText(SessionPath,JsonSerializer.Serialize(new{processId=runningPid,engine=engine.SelectedIndex,runFolder}));}catch{}}
 void RestoreSession(){try{if(!File.Exists(SessionPath))return;var state=JsonNode.Parse(File.ReadAllText(SessionPath))!;int pid=state["processId"]!.GetValue<int>();for(int i=0;i<targets.Items.Count;i++)if(((ProSession)targets.Items[i]!).Id==pid)targets.SelectedIndex=i;engine.SelectedIndex=Math.Clamp(state["engine"]!.GetValue<int>(),0,2);runFolder=state["runFolder"]!.GetValue<string>();foreach(var file in ReadResults())artifacts.Items.Add(new Artifact(file));if(artifacts.Items.Count>0)artifacts.SelectedIndex=0;var answer=Path.Combine(runFolder,"answer.md");if(File.Exists(answer))Say("Agent",File.ReadAllText(answer));}catch{}}
 void Say(string who,string text){chat.AppendText(who+"：\n"+text+"\n\n");chat.SelectionStart=chat.TextLength;chat.ScrollToCaret();}
 void Event(string text){log.Items.Add(DateTime.Now.ToString("HH:mm:ss")+"  "+text);log.TopIndex=Math.Max(0,log.Items.Count-1);status.Text=text;}
 void LoadSessions(){if(busy)return;int selected=(targets.SelectedItem as ProSession)?.Id??0;var sessions=Process.GetProcessesByName("ArcGISPro").Select(p=>new ProSession(p.Id,string.IsNullOrWhiteSpace(p.MainWindowTitle)?"ArcGIS Pro（正在启动）":p.MainWindowTitle)).OrderBy(p=>p.Title).ToArray();targets.BeginUpdate();targets.Items.Clear();targets.Items.AddRange(sessions);targets.SelectedIndex=Array.FindIndex(sessions,s=>s.Id==selected);if(targets.SelectedIndex<0&&sessions.Length==1)targets.SelectedIndex=0;targets.EndUpdate();}
 static string FindCodex(){foreach(string folder in (Environment.GetEnvironmentVariable("PATH")??"").Split(Path.PathSeparator)){var file=Path.Combine(folder.Trim('"'),"codex.exe");if(File.Exists(file))return file;}string home=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"OpenAI","Codex","bin");return Directory.Exists(home)?Directory.GetDirectories(home).OrderByDescending(Directory.GetLastWriteTimeUtc).Select(d=>Path.Combine(d,"codex.exe")).FirstOrDefault(File.Exists)??"":"";}
 void LoadProfiles(){profiles.Items.Clear();try{if(File.Exists(ConfigPath)){var cfg=JsonNode.Parse(File.ReadAllText(ConfigPath))!;foreach(var p in cfg["profiles"]!.AsArray()){if(p?["protocol"]?.GetValue<string>()=="chat")profiles.Items.Add(new Profile(p["id"]!.GetValue<string>(),p["provider"]!.GetValue<string>(),p["model"]!.GetValue<string>()));}for(int i=0;i<profiles.Items.Count;i++)if(((Profile)profiles.Items[i]!).Id==cfg["activeId"]!.GetValue<string>())profiles.SelectedIndex=i;if(profiles.SelectedIndex<0&&profiles.Items.Count>0)profiles.SelectedIndex=0;}}catch(Exception ex){Event("读取模型配置失败："+ex.Message);}UpdateModelLocal();}
 void UpdateModelLocal(){codex=FindCodex();bool api=engine.SelectedIndex==1;profiles.Visible=api;profiles.Enabled=api&&!busy;settings.Enabled=!busy;if(api)model.Text=profiles.SelectedItem is Profile p?$"API配置：{p.Name} / {p.Model}；模型响应尚未验证":"未配置API模型，请点击“API密钥与模型设置”";else if(engine.SelectedIndex==2)model.Text="DeepSeek Harness：使用客户端已登录账户；模型响应尚未验证（点击测试模型）";else model.Text=codex.Length>0?"Codex程序已找到；登录与模型响应尚未验证（点击“测试模型”）":"未找到Codex程序，请先安装并登录Codex";model.ForeColor=SystemColors.ControlText;UpdateButtons();}
 void UpdateButtons(){send.Enabled=!busy&&connected&&File.Exists(Python)&&(engine.SelectedIndex==0?codex.Length>0:engine.SelectedIndex==2||profiles.SelectedItem!=null);stop.Enabled=busy;targets.Enabled=engine.Enabled=refresh.Enabled=test.Enabled=!busy;profiles.Enabled=!busy&&engine.SelectedIndex==1;settings.Enabled=!busy;}
 static async Task<JsonElement> Pipe(int pid,string action,object args,int timeoutMs=6000){using var token=new CancellationTokenSource(timeoutMs);using var pipe=new NamedPipeClientStream(".","ProCodex-"+pid,PipeDirection.InOut,PipeOptions.Asynchronous);await pipe.ConnectAsync(token.Token);using var writer=new StreamWriter(pipe,new UTF8Encoding(false),4096,true){AutoFlush=true};using var reader=new StreamReader(pipe,new UTF8Encoding(false),false,4096,true);await writer.WriteLineAsync(JsonSerializer.Serialize(new{action,arguments=args}));var line=await reader.ReadLineAsync().WaitAsync(token.Token)??throw new IOException("Pro桥接连接中断");using var json=JsonDocument.Parse(line);if(!json.RootElement.GetProperty("success").GetBoolean())throw new Exception(json.RootElement.GetProperty("error").GetString());return json.RootElement.GetProperty("result").Clone();}
 async Task CheckConnection(){if(checking||busy)return;checking=true;connected=false;send.Enabled=false;
  try{if(targets.SelectedItem is not ProSession p){gis.Text=targets.Items.Count==0?"未连接：没有检测到ArcGIS Pro，请先打开工程":"未连接：检测到多个Pro实例，请选择目标工程";gis.ForeColor=Color.Firebrick;map.Text="地图：—";return;}
   if(!File.Exists(Path.Combine(Endpoints,p.Id+".json"))){gis.Text="未连接：此Pro实例未加载桥接；请保存工程并重启Pro";gis.ForeColor=Color.Firebrick;map.Text="地图：尚未读取";return;}
   string bridge=Path.Combine(root,"AddIn","bin","Release","net6.0-windows","ProCodex.dll");
   if(File.Exists(bridge)){
    using var file=File.OpenRead(bridge);using var pe=new System.Reflection.PortableExecutable.PEReader(file);var metadata=pe.GetMetadataReader();string expected=metadata.GetGuid(metadata.GetModuleDefinition().Mvid).ToString("D");
    using var endpoint=JsonDocument.Parse(File.ReadAllText(Path.Combine(Endpoints,p.Id+".json")));
    if(!endpoint.RootElement.TryGetProperty("buildId",out var build)||build.GetString()!=expected)throw new InvalidOperationException("Pro连接桥尚未加载当前构建，请先保存工程并重启Pro。");
   }
   gis.Text="正在检查Pro连接…";gis.ForeColor=SystemColors.ControlText;var data=await Pipe(p.Id,"get_active_map",new{processId=p.Id});if((targets.SelectedItem as ProSession)?.Id!=p.Id)return;mapUri=data.GetProperty("mapUri").GetString()!;connected=true;gis.Text="已连接 ArcGIS Pro · 最近验证 "+DateTime.Now.ToString("HH:mm:ss");gis.ForeColor=Color.DarkGreen;map.Text=$"地图：{data.GetProperty("name").GetString()}    坐标系 WKID {data.GetProperty("wkid").GetInt32()}    图层 {data.GetProperty("layers").GetArrayLength()} 个";
  }catch(OperationCanceledException){gis.Text="连接检测超时：请检查Pro是否正在启动或忙碌";gis.ForeColor=Color.DarkOrange;}catch(Exception ex){gis.Text="未就绪："+ex.Message;gis.ForeColor=Color.Firebrick;map.Text="地图：无法读取";}finally{checking=false;UpdateButtons();}}
 ProcessStartInfo StartInfo(string exe){var info=new ProcessStartInfo(exe){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8,WorkingDirectory=root};if(codex.Length>0)info.Environment["PATH"]=Path.GetDirectoryName(codex)+Path.PathSeparator+info.Environment["PATH"];return info;}
 async Task Start(bool probe){if(busy)return;await CheckConnection();if(!connected||targets.SelectedItem is not ProSession p){Say("系统","Pro尚未连接或没有活动二维地图，请先处理上方连接提示。");return;}string goal=probe?"仅检查连接并读取当前地图和图层，回复是否成功。不要修改地图，不做分析，不导出文件。":input.Text.Trim();if(goal.Length==0){input.Focus();return;}string resume=(!probe&&engine.SelectedIndex==1)?ResumeConversation(p.Id):"";busy=true;stopRequested=false;runningPid=p.Id;runFolder="";errors.Clear();artifacts.Items.Clear();UpdateButtons();if(!probe)input.Clear();Say("你",probe?"测试模型连接":goal);model.Text="模型：正在连接，等待首次响应…";model.ForeColor=Color.DarkOrange;Event("正在启动Agent…");
  try{var info=StartInfo(Python);info.ArgumentList.Add("-X");info.ArgumentList.Add("utf8");info.ArgumentList.Add(Path.Combine(root,"agent",engine.SelectedIndex==0?"codex.py":engine.SelectedIndex==2?"deepseek.py":"run.py"));info.ArgumentList.Add("--pid");info.ArgumentList.Add(p.Id.ToString());if(engine.SelectedIndex==1&&profiles.SelectedItem is Profile profile){info.ArgumentList.Add("--profile");info.ArgumentList.Add(profile.Id);}if(resume.Length>0){info.ArgumentList.Add("--resume");info.ArgumentList.Add(resume);Event("已接续上轮对话与工具回执；将核实现有成果后继续。");}info.ArgumentList.Add("--");info.ArgumentList.Add(goal);runner=new Process{StartInfo=info};runner.Start();var stderr=runner.StandardError.ReadToEndAsync();string? line;var answer=new StringBuilder();bool response=false;
   while((line=await runner.StandardOutput.ReadLineAsync())!=null){if(line.StartsWith("GIS_AGENT_RUN ")){runFolder=line.Substring(14).Trim();continue;}if(line.StartsWith("in_progress ")||line.TrimStart().StartsWith("调用 ")){response=true;model.Text="模型已响应 · 正在调用Pro工具";model.ForeColor=Color.DarkGreen;Event(Friendly(line));}else if(line.StartsWith("completed ")||line.StartsWith("failed ")||line.StartsWith("模型决策轮次")){Event(Friendly(line));}else if(!line.StartsWith("引擎退出码："))answer.AppendLine(line);}
   await runner.WaitForExitAsync();errors.Append(await stderr);var receipts=ReadResults();foreach(var file in receipts)artifacts.Items.Add(new Artifact(file));if(artifacts.Items.Count>0)artifacts.SelectedIndex=0;
   var outcome=ReadRunOutcome();if(engine.SelectedIndex==1&&outcome.Message.Length>0)Say("Agent",outcome.Message);else if(answer.Length>0)Say("Agent",answer.ToString().Trim());if(stopRequested){model.Text="任务已停止；已生成文件保留";model.ForeColor=Color.DarkOrange;Event("用户已停止本轮任务");}else if(outcome.IsTurnLimit){model.Text="达到本轮决策上限 · 可继续任务";model.ForeColor=Color.DarkOrange;Say("系统",outcome.LimitNotice);Event(outcome.LimitNotice);}else if(outcome.Status=="partial"){model.Text="模型已响应 · 本轮任务未完成，请查看Agent说明";model.ForeColor=Color.DarkOrange;Event("Agent已返回部分完成状态；已有处理结果保留，未完成步骤见回复。");}else if(outcome.Status=="interrupted"){model.Text="请求未完成 · 请查看具体原因";model.ForeColor=Color.Firebrick;Event(outcome.Message);}else if(runner.ExitCode!=0){model.Text="程序未正常结束，请查看运行记录";model.ForeColor=Color.Firebrick;Event("Agent异常退出，退出码 "+runner.ExitCode);if(errors.Length>0)Event(errors.ToString().Length>700?errors.ToString()[..700]:errors.ToString());}
   else if(receipts.Count>0){Event("已生成地图成果并收到实际导出回执，可在“地图成果”中打开。");model.Text="模型已响应 · 本轮已交付地图";model.ForeColor=Color.DarkGreen;}
   else{Event("本轮已结束，未生成新的地图文件；请查看Agent回复。");if(response){model.Text="模型已响应 · Pro工具连接已验证";model.ForeColor=Color.DarkGreen;}else{model.Text="本轮结束，尚未验证模型工具调用";}}
  }catch(Exception ex){Say("系统","无法完成请求："+ex.Message);model.Text="请求失败："+ex.Message;model.ForeColor=Color.Firebrick;Event(ex.Message);}finally{runner?.Dispose();runner=null;busy=false;SaveSession();UpdateButtons();await CheckConnection();}}
 string ResumeConversation(int processId){try{string file=Path.Combine(runFolder,"conversation.json");using var state=JsonDocument.Parse(File.ReadAllText(file));return state.RootElement.GetProperty("processId").GetInt32()==processId&&state.RootElement.TryGetProperty("mapUri",out var priorMap)&&priorMap.GetString()==mapUri?file:"";}catch{return "";}}
 RunOutcome ReadRunOutcome(){try{return RunOutcome.Parse(File.ReadAllText(Path.Combine(runFolder,"run.json")));}catch{return new("","","",null);}}
 static string Friendly(string line){var names=new Dictionary<string,string>{{"list_sessions","查找Pro连接"},{"get_active_map","读取当前地图"},{"get_analysis_context","检查数据与可用工具"},{"inspect_layer","核验图层数据"},{"start_analysis","提交数据处理"},{"get_analysis_job","查询处理进度"},{"style_raster","设置栅格配色"},{"set_layer_presentation","设置图层与标注"},{"set_layer_visibility","调整图层显隐"},{"export_map","生成布局并导出地图"}};foreach(var pair in names)if(line.Contains(pair.Key))return (line.StartsWith("failed")?"失败：":line.StartsWith("completed")?"完成：":"正在：")+pair.Value;return line;}
 IEnumerable<(string Name,JsonElement Data)> Results(){if(!Directory.Exists(runFolder))yield break;string events=Path.Combine(runFolder,"events.jsonl");if(File.Exists(events)){foreach(string line in File.ReadLines(events)){JsonDocument? doc=null;try{doc=JsonDocument.Parse(line);}catch(JsonException){}if(doc==null)continue;using(doc){var e=doc.RootElement;if(!e.TryGetProperty("item",out var item)||!item.TryGetProperty("type",out var type)||type.GetString()!="mcp_tool_call"||!e.TryGetProperty("type",out var et)||et.GetString()!="item.completed")continue;if(item.TryGetProperty("result",out var result)&&result.ValueKind==JsonValueKind.Object&&result.TryGetProperty("content",out var content))foreach(var block in content.EnumerateArray()){JsonDocument? inner=null;try{inner=JsonDocument.Parse(block.GetProperty("text").GetString()!);}catch{}if(inner!=null){using(inner)yield return(item.GetProperty("tool").GetString()!,inner.RootElement.Clone());}}}}}
  else{string file=Path.Combine(runFolder,"run.json");if(!File.Exists(file))yield break;JsonDocument? doc=null;try{doc=JsonDocument.Parse(File.ReadAllText(file));}catch{}if(doc!=null)using(doc){foreach(var e in doc.RootElement.GetProperty("events").EnumerateArray()){if(e.GetProperty("kind").GetString()!="tool_result")continue;var r=e.GetProperty("result");if(r.TryGetProperty("isError",out var err)&&err.GetBoolean())continue;foreach(var b in r.GetProperty("content").EnumerateArray()){JsonDocument? inner=null;try{inner=JsonDocument.Parse(b.GetProperty("text").GetString()!);}catch{}if(inner!=null)using(inner)yield return(e.GetProperty("name").GetString()!,inner.RootElement.Clone());}}}}
 }
 List<string> ReadResults(){var files=new List<string>();try{foreach(var (name,data) in Results())if(name=="export_map")foreach(string key in new[]{"png","pdf"})if(data.TryGetProperty(key,out var p)&&p.GetString() is string file&&File.Exists(file)&&new FileInfo(file).Length>0)files.Add(file);}catch(Exception ex){Event("读取成果回执失败："+ex.Message);}return files.Distinct().ToList();}
 async Task Stop(){if(!busy)return;stopRequested=true;stop.Enabled=false;Event("正在停止模型并核实本轮Pro任务…");try{if(runner is{HasExited:false})runner.Kill(true);var jobs=new Dictionary<string,bool>();foreach(var (name,data) in Results())if(data.TryGetProperty("jobId",out var id)&&data.TryGetProperty("terminal",out var terminal))jobs[id.GetString()!]=terminal.GetBoolean();foreach(var job in jobs.Where(j=>!j.Value)){var result=await Pipe(runningPid,"cancel_analysis_job",new{processId=runningPid,jobId=job.Key},10000);Event(result.GetProperty("terminal").GetBoolean()?"Pro任务已进入终态":"已请求取消Pro任务，工具可能仍在退出，请保留Pro窗口");}Say("系统","已停止模型进程；本轮已识别的后台任务已发送取消请求，已生成文件保留。可在运行记录中检查结果。");}catch(Exception ex){Say("系统","停止时无法确认所有Pro任务状态："+ex.Message+"。请检查Pro，不要重复提交分析。");}}
 async Task TestApi(){if(busy||profiles.SelectedItem is not Profile p)return;busy=true;stopRequested=false;runFolder="";UpdateButtons();model.Text="正在实际测试API模型响应…";model.ForeColor=Color.DarkOrange;
  try{var cfg=JsonNode.Parse(File.ReadAllText(ConfigPath))!;var profile=cfg["profiles"]!.AsArray().Single(n=>n!["id"]!.GetValue<string>()==p.Id)!;string dotnet=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"dotnet","dotnet.exe");var info=StartInfo(dotnet);info.RedirectStandardInput=true;info.ArgumentList.Add(Path.Combine(root,"agent","transport","bin","Release","net6.0","ModelTransport.dll"));info.ArgumentList.Add(p.Id);using var process=Process.Start(info)!;runner=process;process.StandardInput.WriteLine(JsonSerializer.Serialize(new{model=p.Model,messages=new[]{new{role="user",content="仅回复：连接成功。"}},max_tokens=1024,stream=false,thinking=profile["disableThinking"]?.GetValue<bool>()==true?new{type="disabled"}:null}));process.StandardInput.Close();var output=await process.StandardOutput.ReadToEndAsync();await process.WaitForExitAsync();using var response=JsonDocument.Parse(output);if(response.RootElement.TryGetProperty("error",out var error))throw new Exception(error.GetString());var message=response.RootElement.GetProperty("choices")[0].GetProperty("message").GetProperty("content").GetString();if(string.IsNullOrWhiteSpace(message)||response.RootElement.GetProperty("choices")[0].GetProperty("finish_reason").GetString()=="length")throw new Exception("模型回复为空或被截断，请增大输出上限后再测试。");model.Text="API模型已实际响应 · "+p.Name+" / "+p.Model+" · "+DateTime.Now.ToString("HH:mm:ss");model.ForeColor=Color.DarkGreen;Say("系统","API测试成功，模型回复："+message);}catch(Exception ex){model.Text=stopRequested?"API测试已停止":"API测试失败："+ex.Message;model.ForeColor=Color.Firebrick;Say("系统",model.Text);}finally{runner=null;busy=false;UpdateButtons();}}
}
